function applyTheme(concept){
  const [primary,secondary,a,b]=conceptThemes[concept.id]||conceptThemes.replication;
  const root=document.documentElement;
  root.style.setProperty('--concept',primary);
  root.style.setProperty('--concept2',secondary);
  root.style.setProperty('--scene-a',a);
  root.style.setProperty('--scene-b',b);
  root.style.setProperty('--scene-c','#070b12');
  keyLight.color.set(primary);fillLight.color.set(secondary);accentLight.color.set(secondary);
}

const $ = (id) => document.getElementById(id);
const viewport = $('scene-viewport');
const renderer = new THREE.WebGLRenderer({antialias:true,alpha:true});
