camera.position.set(0,0,10.5);
scene.add(new THREE.AmbientLight(0x8598b8,1.25));
const keyLight = new THREE.PointLight(0x7bffc9,32,22);keyLight.position.set(-2,3,5);scene.add(keyLight);
const fillLight = new THREE.PointLight(0x5095ff,22,24);fillLight.position.set(3,-2,4);scene.add(fillLight);
const accentLight = new THREE.PointLight(0xb47aff,14,18);accentLight.position.set(0,-3,3);scene.add(accentLight);
const world = new THREE.Group();scene.add(world);
const palette={client:0x65b8ff,leader:0x72edbf,replica:0x49d5c3,router:0xb393ff,shard:0x79a9ff,candidate:0xff88aa,wal:0xffd166,storage:0x94a3b8,cache:0xfb7185,index:0xf97316,coordinator:0xa78bfa,broker:0xc084fc,log:0xfacc15,consumer:0x34d399,kernel:0xa78bfa,scheduler:0x38bdf8,thread:0x34d399,memory:0x60a5fa,hardware:0xfbbf24,compiler:0xfbbf24,runtime:0x22d3ee,lock:0xfb7185};
