let utterance=null,speechPaused=false,speechStarted=0,elapsedBeforePause=0,timer=null,narrationActive=false,speechRun=0,speedIndex=1,resumeIndex=0,fullNarration='',voiceMode='clear';const speeds=[.75,.85,.95,1.05,1.15];
let availableVoices=[],preferredVoices=[],voiceSelectionMade=false;
const voiceProfiles={clear:{rate:.94,pitch:1.02,label:'clear English voices'},female:{rate:.91,pitch:1.08,label:'female English voices'},calm:{rate:.82,pitch:.98,label:'calm English voices'}};
function voiceRegionLabel(voice){try{const locale=new Intl.Locale(voice.lang);const language=new Intl.DisplayNames(['en'],{type:'language'}).of(locale.language);const region=locale.region?new Intl.DisplayNames(['en'],{type:'region'}).of(locale.region):'';return region?`${language} (${region})`:language;}catch{return voice.lang;}}
function isLowQualityVoice(voice){return /espeak|festival|flite|compact|novelty|whisper|croak|zarvox|bells|boing/i.test(voice.name);}
function voiceScore(voice){const name=voice.name.toLowerCase(),lang=voice.lang.toLowerCase();let score=lang.startsWith('en-us')?48:lang.startsWith('en-gb')?38:lang.startsWith('en-au')?34:lang.startsWith('en')?26:0;if(/natural|neural|premium|enhanced|online/.test(name))score+=55;if(/google us english|microsoft/.test(name))score+=32;if(/samantha|aria|ava|jenny|zira|susan|hazel|sara|karen|moira|tessa|victoria|fiona|catherine|emma|amy|joanna|salli|female/.test(name))score+=28;if(isLowQualityVoice(voice))score-=90;if(voice.default)score+=6;return score;}
function isLikelyFemaleVoice(voice){return /samantha|aria|ava|jenny|zira|susan|hazel|sara|karen|moira|tessa|victoria|fiona|catherine|emma|amy|female|google.*english.*female|sfg#female/i.test(voice.name);}
function populateVoices(){if(!('speechSynthesis'in window)){$('voice-select').disabled=true;$('voice-select').innerHTML='<option value="">Audio unavailable</option>';$('voice-hint').textContent='Speech voices are not supported in this browser.';return;}const chosen=$('voice-select').value;availableVoices=window.speechSynthesis.getVoices();const englishVoices=availableVoices.filter(v=>/^en(?:-|$)/i.test(v.lang));const cleanVoices=englishVoices.filter(v=>!isLowQualityVoice(v));const base=cleanVoices.length?cleanVoices:englishVoices;const femaleVoices=base.filter(isLikelyFemaleVoice).sort((a,b)=>voiceScore(b)-voiceScore(a));const modeVoices=voiceMode==='female'&&femaleVoices.length?femaleVoices:base.sort((a,b)=>voiceScore(b)-voiceScore(a));preferredVoices=modeVoices.slice(0,4);const prefix=voiceMode==='female'&&femaleVoices.length?'Female · ':voiceMode==='calm'?'Calm · ':'Clear · ';const options=[...preferredVoices.map(v=>new Option(`${prefix}${v.name} · ${voiceRegionLabel(v)}`,v.voiceURI))];if(!options.length)options.push(new Option('Browser default voice',''));$('voice-select').replaceChildren(...options);if(preferredVoices.some(v=>v.voiceURI===chosen))$('voice-select').value=chosen;else if(!voiceSelectionMade&&preferredVoices.length)$('voice-select').value=preferredVoices[0].voiceURI;const fallback=base===englishVoices&&cleanVoices.length===0;const profile=voiceProfiles[voiceMode];$('voice-hint').textContent=preferredVoices.length?`Showing up to 4 ${profile.label}${fallback?' available in this browser. Install natural system voices for better clarity.':'.'}`:'No English voices found; using the browser default.';}
if('speechSynthesis'in window){populateVoices();window.speechSynthesis.addEventListener('voiceschanged',populateVoices);}
else populateVoices();
function durationText(seconds){const n=Math.max(0,Math.floor(seconds));return `0:${String(n).padStart(2,'0')}`;}
function resetAudio(){clearInterval(timer);$('audio-progress').style.width='0%';$('audio-current').textContent='0:00';$('audio-play').setAttribute('aria-label','Play audio description');$('audio-play').innerHTML='<span class="play-symbol">▶</span>';const estimate=Math.max(15,Math.round(concepts[current].narration.split(/\s+/).length/2.1));$('audio-total').textContent=durationText(estimate);$('audio-duration').textContent=`~ 0:${String(estimate).padStart(2,'0')}`;elapsedBeforePause=0;speechPaused=false;}
function stopSpeech(){speechRun++;if('speechSynthesis'in window){window.speechSynthesis.cancel();}utterance=null;clearInterval(timer);speechPaused=false;narrationActive=false;speechStarted=0;resumeIndex=0;}
function updateAudio(){if(!speechStarted)return;const elapsed=elapsedBeforePause+(speechPaused?0:(Date.now()-speechStarted)/1000);const total=parseInt($('audio-total').textContent.split(':')[1],10)||1;$('audio-current').textContent=durationText(elapsed);$('audio-progress').style.width=`${Math.min(100,elapsed/total*100)}%`;}
function speakSegment(fromIndex=0,resuming=false){clearInterval(timer);const run=++speechRun;const profile=voiceProfiles[voiceMode];utterance=new SpeechSynthesisUtterance(fullNarration.slice(fromIndex));utterance.rate=Math.min(1.2,speeds[speedIndex]*profile.rate);utterance.pitch=profile.pitch;utterance.volume=1;utterance.voice=availableVoices.find(v=>v.voiceURI===$('voice-select').value)||preferredVoices[0]||null;utterance.lang=utterance.voice?.lang||'en-US';narrationActive=true;speechStarted=0;utterance.onstart=()=>{if(run!==speechRun)return;$('audio-state').textContent='Playing narration';$('audio-play').setAttribute('aria-label','Pause audio description');$('audio-play').innerHTML='<span class="play-symbol">Ⅱ</span>';speechStarted=Date.now();if(!resuming)elapsedBeforePause=0;clearInterval(timer);timer=setInterval(updateAudio,250);};utterance.onboundary=event=>{if(run!==speechRun)return;resumeIndex=Math.min(fullNarration.length,fromIndex+event.charIndex+(event.charLength||1));};utterance.onend=()=>{if(run!==speechRun)return;resumeIndex=fullNarration.length;narrationActive=false;speechPaused=false;clearInterval(timer);$('audio-state').textContent='Explanation finished';$('audio-play').setAttribute('aria-label','Replay audio description');$('audio-play').innerHTML='<span class="play-symbol">↻</span>';updateAudio();};utterance.onerror=()=>{if(run!==speechRun)return;narrationActive=false;$('audio-state').textContent='Narration unavailable';clearInterval(timer);};window.speechSynthesis.speak(utterance);}
function playSpeech(){if(!('speechSynthesis'in window)){showToast('Audio narration is not supported in this browser.');return;}if(speechPaused){speechPaused=false;speakSegment(resumeIndex,true);return;}window.speechSynthesis.cancel();fullNarration=concepts[current].narration;resumeIndex=0;elapsedBeforePause=0;speakSegment(0,false);}
$('audio-play').addEventListener('click',()=>{if(!('speechSynthesis'in window)){playSpeech();return;}if(speechPaused){playSpeech();return;}if(narrationActive){if(speechStarted)elapsedBeforePause+=(Date.now()-speechStarted)/1000;if(resumeIndex===0&&elapsedBeforePause>0){const estimate=Math.min(fullNarration.length,Math.floor(elapsedBeforePause*12));const nextSpace=fullNarration.indexOf(' ',estimate);resumeIndex=nextSpace<0?estimate:nextSpace+1;}speechPaused=true;speechRun++;window.speechSynthesis.cancel();speechStarted=0;clearInterval(timer);$('audio-state').textContent='Paused';$('audio-play').setAttribute('aria-label','Resume audio description');$('audio-play').innerHTML='<span class="play-symbol">▶</span>';return;}resetAudio();playSpeech();});
$('audio-speed').addEventListener('click',e=>{speedIndex=(speedIndex+1)%speeds.length;e.currentTarget.textContent=`${speeds[speedIndex]}×`;if(narrationActive){const wasPaused=speechPaused;stopSpeech();resetAudio();if(wasPaused)$('audio-state').textContent='Speed changed · press play';else playSpeech();}});
$('voice-select').addEventListener('change',()=>{voiceSelectionMade=true;if(narrationActive||speechPaused){stopSpeech();resetAudio();$('audio-state').textContent='Voice changed · play to hear';}});
document.querySelectorAll('[data-voice-mode]').forEach(button=>button.addEventListener('click',()=>{voiceMode=button.dataset.voiceMode;document.querySelectorAll('[data-voice-mode]').forEach(item=>item.classList.toggle('active',item===button));voiceSelectionMade=false;populateVoices();if(narrationActive||speechPaused){stopSpeech();resetAudio();$('audio-state').textContent='Voice style changed · play to hear';}}));
$('voice-preview').addEventListener('click',()=>{if(!('speechSynthesis'in window)){showToast('Audio narration is not supported in this browser.');return;}stopSpeech();resetAudio();const run=++speechRun,profile=voiceProfiles[voiceMode];utterance=new SpeechSynthesisUtterance('This is a clearer preview of the selected narration voice.');utterance.rate=profile.rate;utterance.pitch=profile.pitch;utterance.volume=1;utterance.voice=availableVoices.find(v=>v.voiceURI===$('voice-select').value)||preferredVoices[0]||null;utterance.lang=utterance.voice?.lang||'en-US';utterance.onstart=()=>{if(run===speechRun)$('audio-state').textContent='Previewing selected voice';};utterance.onend=()=>{if(run===speechRun)$('audio-state').textContent='Ready when you are';};utterance.onerror=()=>{if(run===speechRun)$('audio-state').textContent='Voice preview unavailable';};window.speechSynthesis.speak(utterance);});
let toastTimer;function showToast(message){const toast=$('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600);}
buildMenu();setConcept(0);animate();
